// --- Init ---
static void WasmInit() {
    algo_lib::FDb_Init();
    samp_mdb::FDb_Init();
    samp_mdb::user_Reserve(64);
    samp_mdb::project_Reserve(64);
    samp_mdb::task_Reserve(64);
    samp_mdb::quote_Reserve(64);
}

// --- Insert from ssim string ---
static bool WasmInsertSsim(const std::string& ssim_line) {
    algo::strptr str((char*)ssim_line.c_str(), ssim_line.size());
    algo::strptr type_tag = algo::GetTypeTag(str);

    if (type_tag == "samp_mdb.User") {
        samp_mdb::User* row = samp_mdb::user_AllocMaybe();
        if (!row) return false;
        if (!samp_mdb::User_ReadStrptrMaybe(*row, str)) {
            samp_mdb::user_Delete(*row);
            return false;
        }
        if (!samp_mdb::user_XrefMaybe(*row)) {
            samp_mdb::user_Delete(*row);
            return false;
        }
        return true;
    }
    if (type_tag == "samp_mdb.Project") {
        samp_mdb::Project* row = samp_mdb::project_AllocMaybe();
        if (!row) return false;
        if (!samp_mdb::Project_ReadStrptrMaybe(*row, str)) {
            samp_mdb::project_Delete(*row);
            return false;
        }
        if (!samp_mdb::project_XrefMaybe(*row)) {
            samp_mdb::project_Delete(*row);
            return false;
        }
        return true;
    }
    if (type_tag == "samp_mdb.Task") {
        samp_mdb::Task* row = samp_mdb::task_AllocMaybe();
        if (!row) return false;
        if (!samp_mdb::Task_ReadStrptrMaybe(*row, str)) {
            samp_mdb::task_Delete(*row);
            return false;
        }
        if (!samp_mdb::task_XrefMaybe(*row)) {
            samp_mdb::task_Delete(*row);
            return false;
        }
        return true;
    }
    if (type_tag == "samp_mdb.Quote") {
        samp_mdb::Quote* row = samp_mdb::quote_AllocMaybe();
        if (!row) return false;
        if (!samp_mdb::Quote_ReadStrptrMaybe(*row, str)) {
            samp_mdb::quote_Delete(*row);
            return false;
        }
        if (!samp_mdb::quote_XrefMaybe(*row)) {
            samp_mdb::quote_Delete(*row);
            return false;
        }
        return true;
    }
    return false;
}

// --- Serialize to ssim ---
static std::string WasmToSsim(const std::string& type, const std::string& key) {
    algo::strptr k((char*)key.c_str(), key.size());
    algo::cstring out;
    if (type == "user") {
        samp_mdb::User* row = samp_mdb::ind_user_Find(k);
        if (row) samp_mdb::User_Print(*row, out);
    } else if (type == "project") {
        samp_mdb::Project* row = samp_mdb::ind_project_Find(k);
        if (row) samp_mdb::Project_Print(*row, out);
    } else if (type == "task") {
        samp_mdb::Task* row = samp_mdb::ind_task_Find(k);
        if (row) samp_mdb::Task_Print(*row, out);
    }
    return to_str(out);
}

// --- User list via zd_user ---
static val UserList() {
    val arr = val::array();
    int i = 0;
    for (samp_mdb::User* row = samp_mdb::zd_user_First(); row; row = samp_mdb::zd_user_Next(*row)) {
        val obj = val::object();
        obj.set("user", to_str(row->user));
        obj.set("email", to_str(row->email));
        obj.set("role", to_str(row->role));
        arr.set(i++, obj);
    }
    return arr;
}

static int UserCount() {
    return samp_mdb::zd_user_N();
}

