// --- User find via ind_user ---
static val UserFind(const std::string& key) {
    samp_mdb::User* row = samp_mdb::ind_user_Find(algo::strptr((char*)key.c_str(), key.size()));
    if (!row) return val::null();
    val obj = val::object();
    obj.set("user", to_str(row->user));
    obj.set("email", to_str(row->email));
    obj.set("role", to_str(row->role));
    return obj;
}

// --- Project find via ind_project ---
static val ProjectFind(const std::string& key) {
    samp_mdb::Project* row = samp_mdb::ind_project_Find(algo::strptr((char*)key.c_str(), key.size()));
    if (!row) return val::null();
    val obj = val::object();
    obj.set("project", to_str(row->project));
    obj.set("description", to_str(row->description));
    obj.set("status", to_str(row->status));
    return obj;
}

// --- Task find via ind_task ---
static val TaskFind(const std::string& key) {
    samp_mdb::Task* row = samp_mdb::ind_task_Find(algo::strptr((char*)key.c_str(), key.size()));
    if (!row) return val::null();
    val obj = val::object();
    obj.set("task", to_str(row->task));
    obj.set("title", to_str(row->title));
    obj.set("priority", (int)row->priority);
    obj.set("status", to_str(row->status));
    obj.set("p_project", to_str(row->p_project));
    obj.set("p_user", to_str(row->p_user));
    return obj;
}

